import dataset from "../../public/data/elements.json";
import type { ChemicalElement, ElementDataset } from "@/types/element";

/**
 * Single entry point for element data. The JSON is generated by
 * scripts/build-elements.mjs; its shape is enforced by tests/element-data.test.ts.
 */
const typed = dataset as ElementDataset;

export const ELEMENT_DATA_META = typed.meta;

export const ELEMENTS: readonly ChemicalElement[] = typed.elements;

const BY_NUMBER = new Map(ELEMENTS.map((el) => [el.number, el]));

export function getElementByNumber(number: number): ChemicalElement | undefined {
  return BY_NUMBER.get(number);
}
